const raw = String($json.output ?? $json.text ?? $json.message ?? '').trim();
const steps = Array.isArray($json.intermediateSteps) ? $json.intermediateSteps : [];

function recoverMessage(value) {
  if (value === null || value === undefined) return '';
  if (Array.isArray(value)) {
    return value.map(recoverMessage).filter(Boolean).join('\n');
  }
  if (typeof value === 'object') {
    return recoverMessage(value.message ?? value.output ?? value.text ?? value.error ?? '');
  }
  const text = String(value).trim();
  if (!text) return '';
  try {
    return recoverMessage(JSON.parse(text));
  } catch {
    return text;
  }
}

const toolMessages = steps
  .map(step => recoverMessage(step?.observation))
  .filter(Boolean);
let output = toolMessages.length ? toolMessages.join('\n') : raw;
let toolCall = null;
if (/^Calling\s+.+?\s+with input\s*:/i.test(output)) {
  const inputMarker = output.match(/\bwith input\s*:/i);
  if (inputMarker) {
    const jsonStart = inputMarker.index + inputMarker[0].length;
    try {
      toolCall = JSON.parse(output.slice(jsonStart).trim());
    } catch {}
  }
  output = toolCall
    ? 'Ejecutando el comando local.'
    : 'No pude interpretar la llamada interna del comando.';
}
if (!output) output = 'No pude responder.';
return [{ json: {
  output: output.replace(/[*_#`~]/g, '').trim(),
  ...(toolCall ? { toolCall } : {}),
} }];
